-- ************************************** CRM.OPPORTUNITY
CREATE TABLE IF NOT EXISTS CRM.OPPORTUNITY
(
 OPPORTUNITY_ID char(18) NOT NULL COMMENT 'A unique 18-character identifier for each sales opportunity, serving as the primary key and used for precise tracking and referencing throughout the CRM system.',
 NAME           varchar(120) NOT NULL COMMENT 'A descriptive name for the opportunity, capturing the essence of the potential deal (e.g., ''Q1 Enterprise Sale'', ''Strategic Partnership Expansion'') to provide quick context and recognition.',
 ACC_ID         char(18) COMMENT 'Foreign key referencing the associated account, establishing a critical link between the opportunity and the specific customer or organization, enabling comprehensive sales relationship tracking.',
 CLOSE_DATE     date COMMENT 'The projected or actual date of opportunity closure, crucial for sales forecasting, pipeline management, and tracking the expected timeline of potential revenue generation.',
 STAGE          varchar(40) COMMENT 'Represents the current progression of the opportunity within the sales pipeline, tracking its movement from initial prospecting to final resolution (e.g., Prospecting, Negotiation, Proposal, Closed Won, Closed Lost).',
 AMOUNT         decimal(18,2) COMMENT 'The total potential monetary value of the opportunity, expressed in decimal format with two decimal places, representing the expected revenue if the deal is successfully closed.',
 PROBABILITY    decimal(5,2) COMMENT 'A percentage-based metric indicating the estimated likelihood of successfully closing the opportunity, derived from historical data, sales team assessment, and deal-specific factors.',
 CREATED_DATE   date COMMENT 'The system-recorded date of opportunity creation, providing a timestamp for when the sales opportunity was first entered into the CRM system for tracking and historical analysis.',
 ADDRESS_1      string NOT NULL,

 CONSTRAINT PK_OPPORTUNITY PRIMARY KEY ( OPPORTUNITY_ID ),
 CONSTRAINT ACC_ID FOREIGN KEY ( ACC_ID ) REFERENCES CRM.ACCOUNT ( ACC_ID )
)
COMMENT = 'Tracks potential revenue-generating deals, providing visibility into the sales pipeline and supporting revenue forecasting.';
